import 'package:flutter_test/flutter_test.dart';
import 'package:accounting_software/app/features/catalog/fabric_types/presentation/widgets/fabric_type_field_validators.dart';
void main(){group('FabricTypeFieldValidators',(){test('requires a name and code',(){expect(FabricTypeFieldValidators.name(' '),isNotNull);expect(FabricTypeFieldValidators.code(null),isNotNull);});test('enforces schema lengths',(){expect(FabricTypeFieldValidators.name(List.filled(101,'x').join()),isNotNull);expect(FabricTypeFieldValidators.code(List.filled(51,'x').join()),isNotNull);});test('accepts valid values',(){expect(FabricTypeFieldValidators.name('Jersey'),isNull);expect(FabricTypeFieldValidators.code('JER'),isNull);});});}
